<?php
namespace App\Models; use Illuminate\Database\Eloquent\Model; class Invoice extends Model{protected $fillable=['business_id','customer_id','project_id','quotation_id','invoice_number','theme_id','issue_date','due_date','status','currency','subtotal','discount','tax','grand_total','amount_paid','balance','notes','terms','payment_schedule','document_snapshot','created_by_user_id'];protected function casts():array{return ['issue_date'=>'date','due_date'=>'date','payment_schedule'=>'array','document_snapshot'=>'array','subtotal'=>'decimal:2','discount'=>'decimal:2','tax'=>'decimal:2','grand_total'=>'decimal:2','amount_paid'=>'decimal:2','balance'=>'decimal:2'];}public function business(){return $this->belongsTo(Business::class);}public function customer(){return $this->belongsTo(Customer::class);}public function project(){return $this->belongsTo(Project::class);}public function quotation(){return $this->belongsTo(Quotation::class);}public function createdBy(){return $this->belongsTo(User::class,'created_by_user_id');}public function paymentAllocations(){return $this->hasMany(PaymentAllocation::class);}public function sessions(){return $this->hasMany(InvoiceSession::class)->orderBy('sort_order');}}
